-- 6. Seed Scenario Events
IF NOT EXISTS (SELECT 1 FROM [scenario].[ScenarioEvents] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Title] = N'Đợt tấn công Deepfake bầy đàn từ nhóm tội phạm có tổ chức (Event E1)')
BEGIN
    INSERT INTO [scenario].[ScenarioEvents] ([ScenarioVersionId], [Title], [Description], [TriggerType], [TriggerConditionJson], [EventContent], [DisplayOrder], [IsActive])
    VALUES (@ScenarioVersionId_FIN_001_V1, N'Đợt tấn công Deepfake bầy đàn từ nhóm tội phạm có tổ chức (Event E1)', N'Nhóm tội phạm sử dụng thẻ CCCD giả gắn chip và video Deepfake hoán đổi khuôn mặt đã vượt qua bộ lọc eKYC cũ, giải ngân trót lọt hơn 2.5 tỷ VNĐ trong đêm.', N'Manual', NULL, N'Vào rạng sáng ngày Chủ Nhật, hệ thống giám sát gian lận phát hiện đợt tấn công bất thường với hơn 150 hồ sơ đăng ký vay từ cùng một dải địa chỉ IP đặt tại nước ngoài nhưng sử dụng định vị GPS giả mạo tại các tỉnh vùng ven.

Các đối tượng đã sử dụng phần mềm tạo video Deepfake cử động mắt miệng khớp với các câu lệnh của hệ thống eKYC cũ và sử dụng ảnh chụp CCCD thật được mua bán trái phép trên mạng. 85 hồ sơ vay đã được hệ thống phê duyệt tự động giải ngân với tổng thiệt hại hơn 2.5 tỷ VNĐ trước khi bị nhân viên trực ca phát hiện đóng băng cổng thanh toán.

Phòng Quản trị Rủi ro và Phòng Chống gian lận yêu cầu dừng toàn bộ luồng phê duyệt tự động STP, chuyển 100% hồ sơ sang thẩm định thủ công, khiến thời gian phê duyệt bị kéo dài lên 2 ngày và khách hàng trung thực kêu ca khắp mạng xã hội.', 1, 1);
END;
